    incident_next = mo.ui.run_button(label="Check whether Alex has access" if _events else "Request access for Alex", full_width=True, disabled=_checked)
    incident_same = mo.ui.run_button(label="Retry with the same request ID", disabled=not _checked or "same" in _retries, full_width=True)
    incident_new = mo.ui.run_button(label="Retry with a new request ID", disabled=not _checked or "new" in _retries, full_width=True)
    incident_reset = mo.ui.run_button(label="Reset this practice exercise", disabled=not _events)
    _parts = [mo.Html(ui.timeout_status(_events, compared=len(_retries) == 2))]
    if not _checked:
        _parts.append(incident_next)
    else:
        _parts += [mo.md("**Optional: what would a retry do?** Each button starts from its own copy of the account you just checked. Predict the membership count, then try both.\n\nA **request ID** (`operation_id` in code) identifies one intended write. Reusing it asks for the saved receipt. A new ID asks the tool to perform another write."), mo.hstack([incident_same, incident_new], widths="equal", wrap=True)]
        _rows = ui.timeout_comparison(_retries)
        if _rows:
            _parts.append(mo.ui.table(_rows, selection=None, show_search=False, show_column_summaries=False))
        if len(_retries) == 2:
            _parts.append(mo.md("**What to carry into your harness:** after an ambiguous timeout, read the actual state. If you must retry the same intended write, preserve its request ID. In round two, find the agent’s next action after a timeout in Agent Lens and check whether it follows this procedure. [Continue to the state scorer and explanation judge ↓](#evals)."))
    _parts += [mo.accordion({"Show the tool calls, request IDs and returned records": mo.Html(ui.receipt({"main_steps": _events, "retry_branches": {key: practice.attempt_actions(value, "missing-seat") for key, value in _retries.items()}}))}), incident_reset]
    mo.vstack(_parts)
    return (incident_new, incident_next, incident_reset, incident_same,)


